 const shortageMatrix=(()=>{const map=new Map();shortages.forEach(x=>{const key=String(x.staff_id||norm(x.name));if(!map.has(key))map.set(key,{staff_id:x.staff_id||"—",name:x.name,sites:new Set(),hours:{}});const row=map.get(key);if(x.site)row.sites.add(x.site);row.hours[x.date]=(row.hours[x.date]||0)+x.shortage;});return [...map.values()].map(x=>({...x,site:[...x.sites].join(", ")||"—"})).sort((a,b)=>a.name.localeCompare(b.name));})();
 const shortagePageSize=8, shortagePageCount=Math.max(1,Math.ceil(shortageMatrix.length/shortagePageSize)), visibleShortageMatrix=shortageMatrix.slice(shortagePage*shortagePageSize,(shortagePage+1)*shortagePageSize);
 async function loadMaster(f){setErr("");setMasterMessage("");try{const w=new ExcelJS.Workbook();await w.xlsx.load(await f.arrayBuffer());const s=w.worksheets[0];if(!s)throw Error("No worksheet found.");const headers=Array.from({length:s.getRow(1).cellCount},(_,i)=>cell(s.getRow(1).getCell(i+1).value)),ni=headers.findIndex(x=>/^staff name$|^employee name$|^name$/i.test(x)),si=headers.findIndex(x=>/^staff id$/i.test(x)),gi=headers.findIndex(x=>/^gender$|^sex$/i.test(x));if(ni<0||si<0||gi<0)throw Error("Excel must contain Staff Name, Staff ID and Gender columns.");const rows=[],seen=new Set(),issues=[];s.eachRow((r,n)=>{if(n===1)return;const name=cell(r.getCell(ni+1).value).replace(/\\s+/g," ").trim(),staffId=cell(r.getCell(si+1).value).trim(),g=cell(r.getCell(gi+1).value).trim().toUpperCase();if(!name&&!staffId&&!g)return;if(!name||!staffId||!["MALE","FEMALE"].includes(g)){issues.push("Row "+n+": missing name/ID or invalid gender");return;}if(seen.has(staffId)){issues.push("Row "+n+": duplicate Staff ID "+staffId);return;}seen.add(staffId);rows.push({staff_id:staffId,employee_name:name,gender:g.toLowerCase(),is_active:true});});if(issues.length)throw Error(issues.slice(0,8).join("; ")+(issues.length>8?" …":""));if(!rows.length)throw Error("No valid employee records found.");setMasterBusy(true);await dbRequest("employee_master?on_conflict=staff_id",{method:"POST",headers:{"Prefer":"resolution=merge-duplicates,return=representation"},body:JSON.stringify(rows)});await refreshMaster();setMasterMessage(rows.length+" employee records saved to Supabase. Existing Staff IDs were updated.");}catch(e){setErr("Employee Master import failed: "+e.message);}finally{setMasterBusy(false);}}
 async function saveEmployee(e){e.preventDefault();setErr("");setMasterMessage("");const id=String(e.target.staff_id.value||"").trim(),name=String(e.target.employee_name.value||"").trim(),gender=e.target.gender.value;if(!id||!name||!["Male","Female"].includes(gender)){setErr("Enter Staff ID, Staff Name and a valid Gender.");return;}setMasterBusy(true);try{await dbRequest("employee_master?on_conflict=staff_id",{method:"POST",headers:{"Prefer":"resolution=merge-duplicates,return=representation"},body:JSON.stringify({staff_id:id,employee_name:name,gender:gender.toLowerCase(),is_active:true})});setEditEmployee(null);setNewEmployee({staff_id:"",employee_name:"",gender:"Male"});await refreshMaster();setMasterMessage("Employee saved successfully.");}catch(err){setErr("Save failed: "+err.message);}finally{setMasterBusy(false);}}
 async function loadPunch(f){setBusy(true);setErr("");try{const savedEmployees=await refreshMaster();if(!savedEmployees.length)throw Error("No saved Employee Master records found. Please import employees in the Employee Master section first.");const w=new ExcelJS.Workbook();await w.xlsx.load(await f.arrayBuffer());const s=w.getWorksheet("Summary")||w.worksheets[0],cols=[];for(let c=4;c<=s.getRow(1).cellCount;c++){const v=s.getRow(1).getCell(c).value;let d=v instanceof Date?v.toISOString().slice(0,10):"";if(!d){const m=cell(v).match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);if(m)d=m[3]+"-"+m[2].padStart(2,"0")+"-"+m[1].padStart(2,"0");}if(d)cols.push({c,date:d});}
 const mp=new Map();savedEmployees.filter(e=>e.is_active).forEach(e=>{const k=norm(e.name);mp.set(k,[...(mp.get(k)||[]),e]);});const out=[];s.eachRow((r,n)=>{if(n===1)return;const name=cell(r.getCell(2).value),site=cell(r.getCell(3).value);if(!name)return;const match=mp.get(norm(name))||[],gender=match.length===1?match[0].gender:"Unknown";for(const dc of cols){const raw=cell(r.getCell(dc.c).value);if(!raw)continue;const t=raw.split(";").map(x=>x.trim()).filter(Boolean),base={name,site,date:dc.date,raw};if(match.length!==1||gender==="Unknown"){out.push({...base,status:match.length>1?"Duplicate Employee Master Match":"Needs HR Verification"});continue;}if(t.length!==2){out.push({...base,status:t.length===1?"Incomplete Punch":"Multiple Punches – HR Verification"});continue;}const a=mins(t[0]),b=mins(t[1]);if(a===null||b===null){out.push({...base,status:"Invalid Punch Time"});continue;}let actual=b-a;if(actual<0)actual+=1440;if(actual>1080){out.push({...base,punchIn:t[0],punchOut:t[1],status:"Suspicious Duration – HR Verification"});continue;}const required=gender==="Male"?630:540,shortage=required-actual;if(shortage>0)out.push({...base,gender,punchIn:t[0],punchOut:t[1],actual,required,shortage,status:"Shortage"});}});setReport(out);setSource(f.name);setTab("Shortage Report");}catch(e){setErr(e.message||"Unable to read workbook.");}finally{setBusy(false);}}
 async function loadMissingPunch(file){setMissingBusy(true);setErr("");try{const w=new ExcelJS.Workbook();await w.xlsx.load(await file.arrayBuffer());const s=w.getWorksheet("Summary")||w.worksheets[0];if(!s)throw Error("No worksheet found.");const parseDate=(v,fmt="")=>{if(v&&typeof v==="object"&&v.result!==undefined)v=v.result;if(v instanceof Date&&!isNaN(v))return [v.getFullYear(),String(v.getMonth()+1).padStart(2,"0"),String(v.getDate()).padStart(2,"0")].join("-");if(typeof v==="number"&&v>20000&&v<80000){const dt=new Date(Date.UTC(1899,11,30)+Math.round(v)*86400000);return [dt.getUTCFullYear(),String(dt.getUTCMonth()+1).padStart(2,"0"),String(dt.getUTCDate()).padStart(2,"0")].join("-");}const raw=cell(v).trim();const bits=raw.split("-");if(bits.length===3&&bits.every(x=>x.trim()!==""&&Number.isInteger(Number(x)))){let [a,b,d]=bits.map(Number);let y,m,day;if(a>999){y=a;m=b;day=d;}else{day=a;m=b;y=d<100?2000+d:d;}if(y>=2000&&y<=2100&&m>=1&&m<=12&&day>=1&&day<=31)return String(y)+"-"+String(m).padStart(2,"0")+"-"+String(day).padStart(2,"0");}return "";};const empByName=new Map();employees.forEach(e=>{const k=norm(e.name);empByName.set(k,[...(empByName.get(k)||[]),e]);});const byEmployee=new Map();const record=(r)=>{if(!r.date||/leave|holiday/i.test(r.status||""))return;const name=String(r.name||"").trim();if(!name)return;const key=norm(name)+"|"+String(r.site||"").trim();if(!byEmployee.has(key)){const matches=empByName.get(norm(name))||[];byEmployee.set(key,{dates:[],staff_id:matches.length===1?String(matches[0].staff_id):"",name:matches.length===1?matches[0].name:name,site:String(r.site||""),missedInDates:[],missedOutDates:[],singlePunchDates:[],missedIn:false,missedOut:false,matchStatus:matches.length===1?"Matched":matches.length>1?"Duplicate name match":"Not in Employee Master"});}const e=byEmployee.get(key);if(r.missedIn){e.missedIn=true;e.missedInDates.push(r.date);}if(r.missedOut){e.missedOut=true;e.missedOutDates.push(r.date);}if(r.singlePunch)e.singlePunchDates.push(r.date);e.dates.push(r.date);};let dateHeaderRow=-1,cols=[];for(let rr=1;rr<=s.rowCount;rr++){const row=s.getRow(rr),found=[];for(let col=4;col<=row.cellCount;col++){const ce=row.getCell(col),date=parseDate(ce.value,ce.numFmt||"");if(date)found.push({col,date});}if(found.length>cols.length){cols=found;dateHeaderRow=rr;}}if(!cols.length)throw Error("Could not detect date columns in '"+s.name+"'. Date cells may be merged or stored as text in a different format. Please share the original PagarBook Excel file so I can map its exact layout.");s.eachRow((r,n)=>{if(n<=dateHeaderRow)return;const name=cell(r.getCell(2).value),site=cell(r.getCell(3).value);if(!name||/staff name|total|grand total/i.test(name))return;for(const d of cols){const raw=cell(r.getCell(d.col).value);if(!raw.trim())continue;const parts=raw.split(";").map(x=>x.trim()).filter(Boolean);if(parts.length>=2)continue;if(parts.length===1){record({date:d.date,name,site,singlePunch:true});}}});const rows=[...byEmployee.values()].filter(e=>e.missedIn||e.missedOut||e.singlePunchDates.length).map(e=>({...e,date:[...new Set(e.dates)].sort().join(", "),missedInDates:[...new Set(e.missedInDates)].sort().join(", "),missedOutDates:[...new Set(e.missedOutDates)].sort().join(", "),singlePunchDates:[...new Set(e.singlePunchDates)].sort().join(", "),status:[e.missedIn?"Missed Punch In":"",e.missedOut?"Missed Punch Out":"",e.singlePunchDates.length?"Single Punch - Verify":""] .filter(Boolean).join(" / ")}));setMissingRows(rows.sort((a,b)=>a.name.localeCompare(b.name)));setMissingSource(file.name);setMissingFrom("");setMissingTo("");setMissingSite("All sites");setMissingPerson("All employees");}catch(e){setErr("Missing Punch Report: "+(e.message||"Unable to read workbook."));}finally{setMissingBusy(false);}}
 const splitDates=v=>String(v||"").split(",").map(s=>s.trim()).filter(Boolean);
const missingFiltered=missingRows.map(x=>{const inDates=splitDates(x.missedInDates),outDates=splitDates(x.missedOutDates),singleDates=splitDates(x.singlePunchDates);const inFiltered=inDates.filter(d=>(!missingFrom||d>=missingFrom)&&(!missingTo||d<=missingTo)),outFiltered=outDates.filter(d=>(!missingFrom||d>=missingFrom)&&(!missingTo||d<=missingTo)),singleFiltered=singleDates.filter(d=>(!missingFrom||d>=missingFrom)&&(!missingTo||d<=missingTo));const relevant=[...new Set([...inFiltered,...outFiltered,...singleFiltered])].sort();return {...x,missedInDates:inFiltered.join(", "),missedOutDates:outFiltered.join(", "),singlePunchDates:singleFiltered.join(", "),date:relevant.join(", "),missedIn:inFiltered.length>0,missedOut:outFiltered.length>0};}).filter(x=>x.date&&(missingSite==="All sites"||x.site===missingSite)&&(missingPerson==="All employees"||x.name===missingPerson));
 async function exportMissing(){const w=new ExcelJS.Workbook(),s=w.addWorksheet("Missing Punch Report");s.addRow(["Staff ID","Employee Name","Site","Missing Punch In Dates","Missing Punch Out Dates","Single Punch - Verify","Status","Employee Match"]);missingFiltered.forEach(x=>s.addRow([x.staff_id,x.name,x.site,x.missedInDates,x.missedOutDates,x.singlePunchDates,x.status,x.matchStatus]));s.getRow(1).font={bold:true};s.columns.forEach(col=>col.width=22);const b=await w.xlsx.writeBuffer(),u=URL.createObjectURL(new Blob([b])),a=document.createElement("a");a.href=u;a.download="Crescent-Missing-Punch-Report.xlsx";a.click();URL.revokeObjectURL(u);}
 function exportMissingPdf(){const rows=missingFiltered.map(x=>`<tr><td>${escPdf(x.staff_id||"—")}</td><td>${escPdf(x.name)}</td><td>${escPdf(x.site||"—")}</td><td>${splitDates(x.date).map(d=>{const p=d.split("-");return p.length===3?new Date(+p[0],+p[1]-1,+p[2]).toLocaleDateString("en-US",{month:"short",day:"2-digit"}).toUpperCase():d}).map(d=>`<span class="chip">${escPdf(d)}</span>`).join(" ")}</td><td>${escPdf(x.status)}</td><td>${escPdf(x.matchStatus)}</td></tr>`).join("");const win=window.open("","_blank","width=1100,height=800");if(!win){setErr("Please allow pop-ups to export the PDF.");return;}win.document.write(`<!doctype html><html><head><title>Crescent Missing Punch Report</title><style>@page{size:A4 landscape;margin:9mm}*{box-sizing:border-box}html,body{width:100%;margin:0;padding:0}body{font:9px Arial,sans-serif;color:#17232b}h1{font-size:17px;line-height:1.2;margin:0 0 4px}.meta{font-size:9px;color:#52636d;margin-bottom:10px}table{width:100%;table-layout:fixed;border-collapse:collapse}th,td{text-align:left;padding:5px 6px;border-bottom:1px solid #ccd5da;vertical-align:top;overflow-wrap:anywhere}th{background:#edf2f5;font-size:9px}td{font-size:9px}th:nth-child(1){width:7%}th:nth-child(2){width:22%}th:nth-child(3){width:13%}th:nth-child(4){width:30%}th:nth-child(5){width:16%}th:nth-child(6){width:12%}.chip{display:inline-block;white-space:nowrap;border:1px solid #9aabb5;border-radius:4px;padding:2px 4px;margin:1px;font-size:8px;font-weight:bold;line-height:1.2}tr{break-inside:avoid;page-break-inside:avoid}thead{display:table-header-group}@media screen{body{padding:12px}}</style></head><body><h1>Crescent Contractors – Missing Punch Report</h1><div class="meta">${missingFiltered.length} employees · ${new Date().toLocaleDateString()}</div><table><thead><tr><th>Staff ID</th><th>Employee Name</th><th>Site</th><th>Missing Punch Dates / Verify</th><th>Status</th><th>Employee Match</th></tr></thead><tbody>${rows}</tbody></table><script>window.onload=()=>window.print()</script></body></html>`);win.document.close();}
 function escPdf(v){return String(v??"").replace(/[&<>"]/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[ch]));}
 function exportShortagePdf(){const dates=shortageDates;const head=["Staff ID","Employee","Site",...dates.map(d=>{const p=d.split("-");return new Date(+p[0],+p[1]-1,+p[2]).toLocaleDateString("en-US",{month:"short",day:"2-digit"}).toUpperCase();})];const rows=shortageMatrix.map(x=>[x.staff_id,x.name,x.site,...dates.map(d=>x.hours[d]?fmt(x.hours[d]):"—")]);const esc=v=>String(v??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));const htmlRows=rows.map(row=>"<tr>"+row.map(v=>"<td>"+esc(v)+"</td>").join("")+"</tr>").join("");const win=window.open("","_blank","width=1200,height=850");if(!win){setErr("Please allow pop-ups to export PDF.");return;}win.document.write(`<!doctype html><html><head><title>Crescent Daily Working Hours Shortage</title><style>@page{size:A4 landscape;margin:6mm}*{box-sizing:border-box}html,body{width:100%;margin:0;padding:0}body{font:7.5px Arial,sans-serif;color:#17232b}h1{font-size:14px;line-height:1.2;margin:0 0 4px}.meta{font-size:8px;margin-bottom:7px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #cbd5db;padding:5px 1px;text-align:center;vertical-align:middle;overflow-wrap:anywhere;line-height:1.25}th{background:#eaf0f3;font-weight:bold;font-size:7px}td{font-size:7.5px}th:nth-child(1),td:nth-child(1){width:5%}th:nth-child(2),td:nth-child(2){width:13%;text-align:left}th:nth-child(3),td:nth-child(3){width:7%;text-align:left}tr{break-inside:avoid;page-break-inside:avoid}thead{display:table-header-group}</style></head><body><h1>Crescent Contractors – Daily Working Hours Shortage</h1><div class="meta">${shortageMatrix.length} employees · ${shortageDates.length} shortage dates · Total shortage: ${fmt(total)} · Generated ${new Date().toLocaleDateString()}</div><table><thead><tr>${head.map(x=>"<th>"+esc(x)+"</th>").join("")}</tr></thead><tbody>${htmlRows}</tbody></table><script>window.onload=()=>window.print()</script></body></html>`);win.document.close();}
 async function exportXlsx(){const w=new ExcelJS.Workbook(),s=w.addWorksheet("Shortage Report");s.addRow(["Staff ID","Employee Name","Site",...shortageDates.map(d=>{const p=d.split("-");return new Date(+p[0],+p[1]-1,+p[2]).toLocaleDateString("en-US",{month:"short",day:"2-digit"}).toUpperCase();})]);shortageMatrix.forEach(x=>s.addRow([x.staff_id,x.name,x.site,...shortageDates.map(d=>x.hours[d]?fmt(x.hours[d]):"")]));s.getRow(1).font={bold:true};s.columns.forEach((col,i)=>col.width=i===1?28:i<3?18:13);s.views=[{state:"frozen",xSplit:3,ySplit:1}];const b=await w.xlsx.writeBuffer(),u=URL.createObjectURL(new Blob([b])),a=document.createElement("a");a.href=u;a.download="Crescent-Shortage-Report.xlsx";a.click();URL.revokeObjectURL(u);}
 const panel={background:"#102330",border:"1px solid #29414e",borderRadius:14,padding:18};
 return <main style={{minHeight:"100vh",background:"#08151d",color:"#e8eef5",fontFamily:"Arial",padding:24}}><div style={{maxWidth:1450,margin:"auto"}}>
 <header style={{marginBottom:22}}><small style={{color:"#e6b85c",letterSpacing:3}}>CRESCENT CONTRACTORS</small><h1>Attendance &amp; Payroll Portal</h1><span style={{color:"#9fb1bf"}}>HR operations workspace</span></header>
 <nav style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:20}}>{tabs.map(t=><button key={t} onClick={()=>{setTab(t);setAuthError("");}} style={{background:tab===t?"#d5a84e":"#102330",color:tab===t?"#101820":"#cbd6dd",border:"1px solid #36515f",borderRadius:9,padding:11}}>{t}</button>)}</nav>
 {err&&<p style={{color:"#ffb8ae"}}>{err}</p>}
 {tab==="Overview"&&<section style={panel}><h2>Attendance &amp; Payroll Overview</h2><p>Upload Employee Master and the PagarBook Punch Report to generate daily shortage details. No salary deduction is made automatically.</p><p>{employees.length} Employee Master records loaded · {shortages.length} shortage records</p></section>}
 {tab==="Employee Master"&&<section style={panel}><h2>Employee Master</h2><p>Import the official PagarBook Excel containing Staff Name, Staff ID and Gender. S.N. is ignored. Records are saved permanently in Supabase.</p><div style={{display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}><input type="file" accept=".xlsx" disabled={masterBusy} onChange={e=>{if(e.target.files?.[0])loadMaster(e.target.files[0]);e.target.value="";}}/><button onClick={refreshMaster} disabled={masterBusy}>Refresh saved records</button><span>{masterBusy?"Saving / loading…":employees.length+" saved employees"}</span></div>{masterMessage&&<p style={{color:"#8ee0b0"}}>{masterMessage}</p>}<h3 style={{marginTop:22}}>Add / Edit Employee</h3><form onSubmit={saveEmployee} style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"end"}}><label>Staff ID<br/><input name="staff_id" required disabled={!!editEmployee} defaultValue={editEmployee?.staff_id||""} key={"id-"+(editEmployee?.staff_id||"new")} style={{padding:9}}/></label><label>Staff Name<br/><input name="employee_name" required defaultValue={editEmployee?.name||""} key={"name-"+(editEmployee?.staff_id||"new")} style={{padding:9,minWidth:230}}/></label><label>Gender<br/><select name="gender" defaultValue={editEmployee?.gender||"Male"} key={"gender-"+(editEmployee?.staff_id||"new")} style={{padding:9}}><option>Male</option><option>Female</option></select></label><button type="submit" disabled={masterBusy}>Save Employee</button>{editEmployee&&<button type="button" onClick={()=>setEditEmployee(null)}>Cancel</button>}</form><div style={{marginTop:20,display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}><input placeholder="Search Staff ID or employee name…" value={masterSearch} onChange={e=>setMasterSearch(e.target.value)} style={{padding:10,minWidth:260}}/><span>{employees.filter(x=>(x.staff_id+" "+x.name).toLowerCase().includes(masterSearch.toLowerCase())).length} matching records</span></div><div style={{overflowX:"auto",marginTop:10}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}><thead><tr>{["Staff ID","Staff Name","Gender","Status","Action"].map(x=><th key={x} style={{textAlign:"left",padding:9,borderBottom:"1px solid #36515f"}}>{x}</th>)}</tr></thead><tbody>{employees.filter(x=>(x.staff_id+" "+x.name).toLowerCase().includes(masterSearch.toLowerCase())).map(x=><tr key={x.staff_id}>{[x.staff_id,x.name,x.gender,x.is_active?"Active":"Inactive"].map((v,i)=><td key={i} style={{padding:9,borderBottom:"1px solid #233b47"}}>{v}</td>)}<td style={{padding:9,borderBottom:"1px solid #233b47"}}><button type="button" onClick={()=>setEditEmployee(x)}>Edit</button></td></tr>)}</tbody></table>{!employees.length&&<p style={{color:"#9fb1bf"}}>No saved employees found. Import the official Excel file to begin.</p>}</div></section>}
 {tab==="Missing Punch Report"&&<section style={panel}><div style={{display:"flex",justifyContent:"space-between",gap:12,flexWrap:"wrap",alignItems:"center"}}><div><h2>Missing Punch Report</h2><p>Only employees with incomplete punch entries are listed. Each employee appears once.</p><small>{missingSource||"Upload PagarBook Punch Report Excel"}</small></div><div style={{display:"flex",gap:8}}><button disabled={!missingFiltered.length} onClick={exportMissing}>Export Excel</button><button disabled={!missingFiltered.length} onClick={exportMissingPdf}>Export PDF</button></div></div><div style={{display:"flex",gap:12,flexWrap:"wrap",alignItems:"center",margin:"14px 0"}}><label>Upload PagarBook report <input type="file" accept=".xlsx" disabled={missingBusy} onChange={e=>{if(e.target.files?.[0])loadMissingPunch(e.target.files[0]);e.target.value="";}}/></label>{missingBusy&&<span>Reading workbook…</span>}<b>{missingRows.length} employees with missing punches</b></div><div style={{display:"flex",gap:12,flexWrap:"wrap",margin:"14px 0"}}><label>From <input type="date" value={missingFrom} onChange={e=>setMissingFrom(e.target.value)}/></label><label>To <input type="date" value={missingTo} onChange={e=>setMissingTo(e.target.value)}/></label><label>Site <select value={missingSite} onChange={e=>setMissingSite(e.target.value)}><option>All sites</option>{[...new Set(missingRows.map(x=>x.site).filter(Boolean))].sort().map(x=><option key={x}>{x}</option>)}</select></label><label>Employee <select value={missingPerson} onChange={e=>setMissingPerson(e.target.value)}><option>All employees</option>{[...new Set(missingRows.map(x=>x.name))].sort().map(x=><option key={x}>{x}</option>)}</select></label></div><div style={{display:"flex",gap:18,flexWrap:"wrap",color:"#e6b85c",marginBottom:12}}><b>{missingFiltered.length} employees</b><b>{missingFiltered.filter(x=>x.missedIn).length} missed punch-in</b><b>{missingFiltered.filter(x=>x.missedOut).length} missed punch-out</b></div><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}><thead><tr>{["Staff ID","Employee Name","Site","Missing Punch Dates / Verify","Status","Employee Match"].map(x=><th key={x} style={{textAlign:"left",padding:9,borderBottom:"1px solid #36515f"}}>{x}</th>)}</tr></thead><tbody>{missingFiltered.map((x,i)=><tr key={i}>{[x.staff_id||"—",x.name,x.site||"—",x.date||"—",x.status,x.matchStatus].map((v,j)=><td key={j} style={{padding:9,borderBottom:"1px solid #233b47",verticalAlign:"middle"}}>{j===3&&v!=="—"?<div style={{display:"flex",gap:5,flexWrap:"wrap",maxWidth:360}}>{String(v).split(",").map(d=>{const parts=d.trim().split("-");const label=parts.length===3?new Date(Number(parts[0]),Number(parts[1])-1,Number(parts[2])).toLocaleDateString("en-US",{month:"short",day:"2-digit"}).toUpperCase():d.trim();return <span key={d} style={{display:"inline-flex",alignItems:"center",padding:"4px 7px",borderRadius:6,background:"#1b3542",border:"1px solid #365766",fontSize:11,fontWeight:600,whiteSpace:"nowrap",color:"#d8e8ef"}}>{label}</span>;})}</div>:v}</td>)}</tr>)}</tbody></table>{!missingFiltered.length&&<p style={{textAlign:"center",color:"#9fb1bf"}}>No missing punch records found. Upload a PagarBook report to check.</p>}</div><p style={{color:"#9fb1bf",fontSize:12}}>Complete IN and OUT pairs are excluded. Each employee appears once. Single-punch dates are listed for verification; the missing side is not guessed.</p></section>}{tab==="Shortage Report"&&<section style={panel}><div style={{display:"flex",justifyContent:"space-between",flexWrap:"wrap"}}><div><h2>Daily Working Hours Shortage</h2><small>{source||"PagarBook Punch Report (28th–27th cycle)"}</small></div><div style={{display:"flex",gap:8}}><button disabled={!shortages.length} onClick={exportXlsx}>Export Excel</button><button disabled={!shortages.length} onClick={exportShortagePdf}>Export PDF</button></div></div>
 <p>Saved Employee Master: <strong>{employees.length} employees</strong> · PagarBook Punch Report <input type="file" accept=".xlsx" onChange={e=>e.target.files?.[0]&&loadPunch(e.target.files[0])}/></p>
 <div style={{display:"flex",gap:12,flexWrap:"wrap",margin:"16px 0"}}><label>From <input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>To <input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><label>Site <select value={site} onChange={e=>setSite(e.target.value)}><option>All sites</option>{sites.map(x=><option key={x}>{x}</option>)}</select></label><label>Employee <select value={person} onChange={e=>setPerson(e.target.value)}><option>All employees</option>{[...new Set(report.map(x=>x.name))].sort().map(x=><option key={x}>{x}</option>)}</select></label></div>
 <div style={{display:"flex",gap:20,marginBottom:16,color:"#e6b85c"}}><b>{shortages.length} shortage dates</b><b>{shortageMatrix.length} employees</b><b>{fmt(total)} total shortage</b></div>{busy&&"Reading workbook…"}
 <div style={{width:"100%",overflow:"hidden"}}><table style={{width:"100%",tableLayout:"fixed",borderCollapse:"collapse",fontSize:11}}><thead><tr>{["Staff ID","Employee","Site",...shortageDates.map(d=>{const p=d.split("-");return new Date(+p[0],+p[1]-1,+p[2]).toLocaleDateString("en-US",{month:"short",day:"2-digit"}).toUpperCase();})].map((x,i)=><th key={i} style={{textAlign:i>2?"center":"left",whiteSpace:"nowrap",padding:"6px 2px",borderBottom:"1px solid #36515f",background:"#102330",fontSize:10}}>{x}</th>)}</tr></thead><tbody>{visibleShortageMatrix.map((x,i)=><tr key={i}><td style={{padding:"6px 3px",borderBottom:"1px solid #233b47",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{x.staff_id}</td><td style={{padding:9,borderBottom:"1px solid #233b47",whiteSpace:"nowrap"}}>{x.name}</td><td style={{padding:9,borderBottom:"1px solid #233b47",whiteSpace:"nowrap"}}>{x.site}</td>{shortageDates.map(d=><td key={d} style={{padding:"6px 1px",borderBottom:"1px solid #233b47",textAlign:"center",whiteSpace:"nowrap",fontSize:10,color:x.hours[d]?"#e6b85c":"#617783",fontWeight:x.hours[d]?700:400}}>{x.hours[d]?fmt(x.hours[d]):"—"}</td>)}</tr>)}</tbody></table>{!shortageMatrix.length&&<p style={{textAlign:"center",color:"#9fb1bf"}}>No shortage records found for the selected filters.</p>}</div>{shortageMatrix.length>shortagePageSize&&<div style={{display:"flex",justifyContent:"center",alignItems:"center",gap:14,marginTop:12,fontSize:12}}><button disabled={shortagePage===0} onClick={()=>setShortagePage(p=>Math.max(0,p-1))}>Previous</button><span>Page {shortagePage+1} of {shortagePageCount} · Showing {shortagePage*shortagePageSize+1}–{Math.min((shortagePage+1)*shortagePageSize,shortageMatrix.length)} of {shortageMatrix.length} employees</span><button disabled={shortagePage+1>=shortagePageCount} onClick={()=>setShortagePage(p=>Math.min(shortagePageCount-1,p+1))}>Next</button></div>}
 <p style={{color:"#9fb1bf",fontSize:12}}>One row per employee. Each date is a separate column; the cell shows the shortage duration for that date. Complete records without a shortage and incomplete punch entries are excluded from this summary. Male required hours: 10h 30m · Female: 9h.</p></section>}
 {tab==="Payroll Import"&&<section style={panel}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:12,flexWrap:"wrap"}}><div><h2>Payroll Import</h2><p>Upload the original PagarBook payroll workbook. Original row values are retained without modifying the source data.</p></div><div style={{display:"flex",gap:8}}><button onClick={loadPayrollHistory} disabled={payrollBusy}>Refresh</button><button onClick={exportPayrollExcel} disabled={!visiblePayrollRows.length}>Export Excel</button><button onClick={exportPayrollPdf} disabled={!visiblePayrollRows.length}>Export PDF</button></div></div><div style={{display:"flex",gap:12,alignItems:"center",flexWrap:"wrap",margin:"14px 0"}}><label>Upload PagarBook Payroll Excel <input type="file" accept=".xlsx,.xlsm" disabled={payrollBusy} onChange={e=>{if(e.target.files?.[0])importPayrollFile(e.target.files[0]);e.target.value="";}}/></label><button onClick={loadPayrollHistory} disabled={payrollBusy}>Load saved imports</button>{payrollBusy&&<b>Processing…</b>}</div>{payrollMessage&&<p style={{color:"#8ee0b0"}}>{payrollMessage}</p>}<div style={{display:"flex",gap:12,flexWrap:"wrap",margin:"12px 0"}}><label>Import <select value={selectedBatch} onChange={e=>setSelectedBatch(e.target.value)}><option value="All imports">All imports</option>{payrollBatches.map(b=><option key={b.id} value={b.id}>{b.file_name} · {new Date(b.imported_at).toLocaleDateString()}</option>)}</select></label><input placeholder="Search employee, Staff ID or payroll value…" value={payrollSearch} onChange={e=>setPayrollSearch(e.target.value)} style={{padding:9,minWidth:280}}/><b>{visiblePayrollRows.length} rows displayed</b></div><div style={{overflowX:"auto",maxHeight:560}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead><tr><th style={{textAlign:"left",padding:8}}>Row</th>{visiblePayrollHeaders.map(h=><th key={h} style={{textAlign:"left",padding:8,whiteSpace:"nowrap"}}>{h}</th>)}</tr></thead><tbody>{visiblePayrollRows.slice(0,500).map(r=><tr key={r.id}><td style={{padding:8,borderTop:"1px solid #29414e"}}>{r.source_row_number}</td>{visiblePayrollHeaders.map(h=><td key={h} style={{padding:8,borderTop:"1px solid #29414e",whiteSpace:"nowrap"}}>{r.raw_data?.values?.[h]??"—"}</td>)}</tr>)}</tbody></table>{!visiblePayrollRows.length&&<p style={{color:"#9fb1bf"}}>No imported payroll rows found. Upload the original PagarBook Excel file to begin.</p>}{visiblePayrollRows.length>500&&<p>Showing first 500 rows on screen. Export Excel/PDF for the complete filtered dataset.</p>}</div><h3>Import history</h3><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead><tr>{["File","Rows","Status","Imported"].map(x=><th key={x} style={{textAlign:"left",padding:8}}>{x}</th>)}</tr></thead><tbody>{payrollBatches.map(b=><tr key={b.id}><td style={{padding:8}}>{b.file_name}</td><td style={{padding:8}}>{b.row_count}</td><td style={{padding:8}}>{b.status}</td><td style={{padding:8}}>{new Date(b.imported_at).toLocaleString()}</td></tr>)}</tbody></table></div><p style={{fontSize:12,color:"#9fb1bf"}}>Public access is enabled as requested: imported payroll records can be viewed by anyone who can access this portal. Do not upload payroll data unless you accept that exposure.</p></section>}
 {tab==="Salary Bill"&&<section style={panel}><div style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"center",flexWrap:"wrap"}}><div><h2>Salary Bill</h2><p>Site-wise salary bill using the approved Crescent September format (columns A–Y only).</p></div><div style={{display:"flex",gap:8}}><button onClick={loadPayrollHistory} disabled={payrollBusy}>Refresh imports</button><button onClick={exportSalaryExcel} disabled={!salaryMappedRows.length}>Export Excel</button><button onClick={exportSalaryPdf} disabled={!salaryMappedRows.length}>Export PDF</button></div></div><div style={{display:"flex",gap:14,alignItems:"center",flexWrap:"wrap",margin:"14px 0"}}><label>Payroll Import <select value={salaryBatch} onChange={e=>{setSalaryBatch(e.target.value);setSalarySite("All sites");}}><option value="">Select an import</option>{payrollBatches.map(b=><option key={b.id} value={b.id}>{b.file_name} · {new Date(b.imported_at).toLocaleDateString()}</option>)}</select></label><label>Salary Month <input type="month" value={salaryMonth} onChange={e=>setSalaryMonth(e.target.value)} /></label><label>Site <select value={salarySite} onChange={e=>setSalarySite(e.target.value)}><option>All sites</option>{salarySites.map(s=><option key={s}>{s}</option>)}</select></label><b>{salaryMappedRows.length} employees</b></div>{payrollBusy&&<p>Loading saved payroll imports…</p>}{!payrollBatches.length&&!payrollBusy&&<p style={{color:"#f2c66d"}}>No payroll import found. Upload the original PagarBook payroll workbook in Payroll Import first.</p>}{salaryMappedRows.length>0&&<><div style={{display:"flex",gap:18,flexWrap:"wrap",color:"#e6b85c",marginBottom:12}}>{["Total CTC","Basic","DA","HRA","Net Payable Amount"].map(h=><b key={h}>{h}: ₹{salaryMoney(salarySum(salaryMappedRows,h))}</b>)}</div><div style={{overflowX:"auto",maxHeight:560}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:12}}><thead><tr>{salaryColumns.map((h,i)=><th key={i} style={{textAlign:"left",padding:8,whiteSpace:"nowrap"}}>{h}</th>)}</tr></thead><tbody>{salaryGroups.map(([siteName,rows])=><React.Fragment key={siteName}>{rows.map(r=><tr key={r.source.id}>{salaryColumns.map((h,j)=><td key={j} style={{padding:"7px 6px",borderTop:"1px solid #29414e",whiteSpace:"nowrap"}}>{salaryDisplay(r.values[h]??"—")}</td>)}</tr>)}<tr style={{fontWeight:700,background:"#1b3542"}}>{salaryColumns.map((h,j)=><td key={j} style={{padding:"8px 6px",borderTop:"2px solid #547080",whiteSpace:"nowrap"}}>{j===23?siteName+" TOTAL":j===24?salaryMoney(salaryTotalFor(rows,"Net Payable Amount")):""}</td>)}</tr><tr><td colSpan={25} style={{height:7,padding:0,border:0}} /></tr></React.Fragment>)}<tr style={{fontWeight:700,background:"#d5a84e",color:"#101820"}}>{salaryColumns.map((h,j)=><td key={j} style={{padding:"9px 6px",borderTop:"2px solid #d5a84e",whiteSpace:"nowrap"}}>{j===23?"GRAND TOTAL":j===24?salaryMoney(salaryTotalFor(salaryMappedRows,"Net Payable Amount")):""}</td>)}</tr></tbody></table></div><p style={{fontSize:12,color:"#9fb1bf"}}>Strict Crescent layout: S.N. through Net Payable Amount only (A–Y). No attendance/work-hour columns or post-Y fields. Site subtotals and grand total are calculated from Net Payable Amount only.</p></>}</section>}{tab==="Payslips"&&<section style={panel}><h2>Payslips</h2><p>Payslip generation will be enabled after the salary bill format and employee-wise salary mapping are confirmed.</p></section>}
 {!["Overview","Employee Master","Shortage Report","Payroll Import","Salary Bill","Payslips"].includes(tab)&&<section style={panel}><h2>{tab}</h2><p>This module remains in the portal navigation. This release is focused on the PagarBook-format Shortage Report.</p></section>}
 </div></main>;
